<?php require_once __DIR__.'/../app/bootstrap.php';require_admin();$active='notices';$pageTitle='বিজ্ঞপ্তি পরিচালনা';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);if(isset($_POST['delete'])){$s=$pdo->prepare('SELECT pdf_path FROM notices WHERE id=?');$s->execute([$id]);$old=$s->fetch();if($old){$pdo->prepare('DELETE FROM notices WHERE id=?')->execute([$id]);require_once __DIR__.'/../app/helpers.php';remove_pdf($old['pdf_path']);}$_SESSION['flash']='বিজ্ঞপ্তি মুছে ফেলা হয়েছে।';}elseif(isset($_POST['toggle'])){$pdo->prepare("UPDATE notices SET status=IF(status='published','draft','published') WHERE id=?")->execute([$id]);$_SESSION['flash']='বিজ্ঞপ্তির অবস্থা পরিবর্তন হয়েছে।';}header('Location: notices.php');exit;}$rows=$pdo->query('SELECT id,title,notice_date,pdf_original_name,status,created_at FROM notices ORDER BY notice_date DESC,id DESC')->fetchAll();$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);require __DIR__.'/_head.php';?><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><div class="panel"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><div><h5 class="mb-1">সকল বিজ্ঞপ্তি</h5><div class="muted small">PDF আপলোড, সম্পাদনা, প্রকাশ/খসড়া এবং মুছে ফেলা</div></div><span class="badge-status bg-light text-dark"><?=count($rows)?>টি বিজ্ঞপ্তি</span></div><div class="table-wrap"><table class="table"><thead><tr><th>শিরোনাম</th><th>তারিখ</th><th>PDF</th><th>অবস্থা</th><th>কাজ</th></tr></thead><tbody><?php foreach($rows as $n):?><tr><td><div class="notice-title"><?=e($n['title'])?></div></td><td><?=e(date_bn($n['notice_date']))?></td><td><span class="small"><i class="fa-solid fa-file-pdf text-danger me-1"></i><?=e($n['pdf_original_name'])?></span><br><a target="_blank" href="../notice.php?id=<?=(int)$n['id']?>">দেখুন</a></td><td><span class="badge-status <?=$n['status']==='published'?'bg-success-subtle text-success':'bg-warning-subtle text-warning-emphasis'?>"><?=$n['status']==='published'?'প্রকাশিত':'খসড়া'?></span></td><td><div class="d-flex gap-1 flex-wrap"><a class="btn btn-sm btn-outline-primary" href="notice-form.php?id=<?=(int)$n['id']?>">সম্পাদনা</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button class="btn btn-sm btn-outline-secondary" name="toggle" value="1"><?=$n['status']==='published'?'খসড়া':'প্রকাশ'?></button></form><form method="post" onsubmit="return confirm('এই বিজ্ঞপ্তি মুছে ফেলবেন?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button class="btn btn-sm btn-outline-danger" name="delete" value="1">মুছুন</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center muted py-5">এখনো কোনো বিজ্ঞপ্তি নেই।</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/_foot.php';?>